using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using Newtonsoft.Json;
public static class FinishSurfaces {
 static string R=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));const string A="Assets/Afrer_Seconds/05.Model/Environment/";
 public static object Run(){if(Application.isPlaying||SceneManager.GetActiveScene().isDirty)throw new Exception("Saved edit required");var original=SceneManager.GetActiveScene().path;AssetDatabase.Refresh(ImportAssetOptions.ForceSynchronousImport);foreach(string f in Directory.GetFiles(A+"Common/Textures","FM_*.png")){var path=f.Replace('\\','/');var ti=(TextureImporter)AssetImporter.GetAtPath(path);ti.textureType=path.Contains("Normal")?TextureImporterType.NormalMap:TextureImporterType.Default;ti.sRGBTexture=!path.Contains("Normal")&&!path.Contains("MetalSmooth");ti.wrapMode=TextureWrapMode.Repeat;ti.mipmapEnabled=true;ti.anisoLevel=8;ti.maxTextureSize=2048;ti.textureCompression=TextureImporterCompression.CompressedHQ;ti.SaveAndReimport();}var records=new List<object>();try{foreach(string floor in new[]{"B5","B4"}){var s=EditorSceneManager.OpenScene("Assets/Afrer_Seconds/01.Scenes/Stage/Level_"+floor+"_Circular.unity");string backup=R+"/SourceAssets/B4_Finish/"+floor+"_surface_before.unity";if(!File.Exists(backup))EditorSceneManager.SaveScene(s,backup,true);var map=new Dictionary<Material,Material>();foreach(var r in s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<MeshRenderer>(true))){var ms=r.sharedMaterials;bool changed=false;for(int i=0;i<ms.Length;i++){var old=ms[i];if(!old||!old.name.StartsWith("FW_"))continue;if(!map.TryGetValue(old,out var m)){string kind=old.name.Contains("CargoFloor")?"CargoFloor":old.name.Contains("CargoWall")?"CargoWall":old.name.Contains("CargoEdge")?"CargoEdge":floor;string n="FM_"+old.name,path=A+floor+"/Materials/"+n+".mat";m=AssetDatabase.LoadAssetAtPath<Material>(path);if(!m){m=new Material(old){name=n};AssetDatabase.CreateAsset(m,path);}foreach(string prop in new[]{"_BaseMap","_MainTex"})if(m.HasProperty(prop))m.SetTexture(prop,AssetDatabase.LoadAssetAtPath<Texture2D>(A+"Common/Textures/FM_"+kind+"_Base.png"));m.SetTexture("_BumpMap",AssetDatabase.LoadAssetAtPath<Texture2D>(A+"Common/Textures/FM_"+kind+"_Normal.png"));m.SetTexture("_MetallicGlossMap",AssetDatabase.LoadAssetAtPath<Texture2D>(A+"Common/Textures/FM_"+kind+"_MetalSmooth.png"));m.SetFloat("_BumpScale",kind==floor?.85f:.95f);m.SetFloat("_Smoothness",1);m.EnableKeyword("_NORMALMAP");m.EnableKeyword("_METALLICSPECGLOSSMAP");m.enableInstancing=true;EditorUtility.SetDirty(m);map[old]=m;}ms[i]=m;changed=true;}if(changed){r.sharedMaterials=ms;PrefabUtility.RecordPrefabInstancePropertyModifications(r);records.Add(new{floor,name=r.name,id=GlobalObjectId.GetGlobalObjectIdSlow(r).ToString()});}}EditorSceneManager.MarkSceneDirty(s);EditorSceneManager.SaveScene(s);}AssetDatabase.SaveAssets();}finally{EditorSceneManager.OpenScene(original);}File.WriteAllText(R+"/SourceAssets/B4_Finish/surfaces_applied.json",JsonConvert.SerializeObject(records,Formatting.Indented));return new{renderers=records.Count};}
}
